const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={user:null,months:[],month:null,page:'patients',patient:null,patientData:null,patientTab:'Summary',chat:false,review:null,reviewStarted:null,reviewTimer:null,patientsPage:1,patientsSearch:'',patientsReview:'',patientsPlatform:'',explorerProvider:'',explorerPlatform:'',explorerPattern:'',explorerActivity:''};
const fmt=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:1});
const pct=n=>`${Number(n||0).toFixed(1)}%`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>{if(!s)return'—';const d=new Date(s);return Number.isNaN(d.getTime())?s:d.toLocaleString('en-US',{timeZone:'America/New_York',month:'numeric',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'})};
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function prefs(){let p={};try{p=JSON.parse(localStorage.getItem('reflect-v20-prefs')||'{}')}catch{};document.documentElement.dataset.themeMode=p.theme||'light';document.documentElement.dataset.a11yColorblind=p.colorSafe?'true':'false';document.documentElement.style.setProperty('--scale',p.scale||1);const fonts={spec:'"IBM Plex Sans","Segoe UI",Arial,sans-serif',roboto:'Roboto,"Segoe UI",Arial,sans-serif',times:'"Times New Roman",Times,serif',segoe:'"Segoe UI",Arial,sans-serif'};document.documentElement.style.setProperty('--body-font',fonts[p.font||'spec']);document.documentElement.style.setProperty('--heading-font',p.font==='times'?fonts.times:(p.font==='roboto'?fonts.roboto:'"IBM Plex Sans Condensed","Segoe UI",Arial,sans-serif'))}
async function api(path,opt={}){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),path.startsWith('/api/analytics')?45000:30000);const headers={'Content-Type':'application/json',...(opt.headers||{})};if(state.user?.csrf&&opt.method&&opt.method!=='GET')headers['X-CSRF-Token']=state.user.csrf;try{const r=await fetch(path,{credentials:'same-origin',...opt,headers,signal:ctrl.signal});const type=r.headers.get('content-type')||'';if(!type.includes('application/json')){if(!r.ok)throw new Error(`Request failed (${r.status})`);return r}const d=await r.json();if(!r.ok)throw new Error(d.error||`Request failed (${r.status})`);return d}catch(e){if(e.name==='AbortError')throw new Error('The request exceeded the dashboard time limit. V20 uses indexed V18.2 summaries and cached/sampled organization distributions for 5M-scale analytics. Retry once; if it repeats, check the server console.');throw e}finally{clearTimeout(timer)}}
function tag(text,kind=''){return `<span class="tag ${kind}">${esc(text)}</span>`}
function login(){return `<main class="login-v20"><section class="login-v20-card"><div class="login-v20-brand"><span class="brand-glyph">✦</span><div><strong>REFLECT</strong><small>Provider Dashboard · V20</small></div></div><div class="login-v20-copy"><span class="tag coral">DEMO ACCESS</span><h1>Sign in</h1><p>Choose a role and open the dashboard. V20 reads the V18.2 billing-master database directly.</p></div><form class="login-form-v20" id="loginForm"><label class="field"><span>Email</span><input id="email" type="email" autocomplete="username" required></label><label class="field"><span>Password</span><input id="password" type="password" autocomplete="current-password" required></label><button class="btn btn-primary" type="submit">Sign in</button></form><div id="loginError" class="login-error"></div><div class="login-v20-divider"><span>Demo accounts</span></div><div id="accounts" class="account-grid compact"><div class="skeleton"></div><div class="skeleton"></div></div><p class="login-v20-foot">Provider = assigned patient panel · Admin = organization analytics · Billing Reviewer = RTM/billing evidence</p></section></main>`}
async function loadAccounts(){try{const d=await api('/api/demo-accounts');$('#accounts').innerHTML=d.accounts.map(a=>`<button class="account-card" data-email="${esc(a.email)}" data-pass="${a.role==='Provider'?d.provider_password:a.role==='Admin'?d.admin_password:d.billing_password}"><div><h4>${esc(a.display_name)}</h4><p>${a.provider_id?`${esc(a.provider_id)} · ${fmt(a.patient_count)} patients`:a.role==='Admin'?'Organization analytics':'RTM / billing review'}</p><code>${esc(a.email)}</code></div><span class="role-chip">${esc(a.role)}</span></button>`).join('');$$('.account-card').forEach(b=>b.onclick=()=>{$('#email').value=b.dataset.email;$('#password').value=b.dataset.pass;$('#email').focus()})}catch(e){$('#accounts').innerHTML=`<div class="error-panel">${esc(e.message)}</div>`}}
function bindLogin(){$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='';try{const d=await api('/api/login',{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value})});state.user=d.user;await boot()}catch(err){$('#loginError').textContent=err.message}};loadAccounts()}
function navItems(){if(state.user.role==='Provider')return [['patients','My Patients'],['overview','Overview'],['providerTime','Provider Time'],['explorer','Explorer'],['engagement','Engagement'],['modules','Modules'],['platform','Platform'],['review','Review Queue'],['billing','Billing & RTM']];if(state.user.role==='Admin')return [['overview','Organization Overview'],['patients','Patients'],['providers','Providers'],['providerTime','Provider Time'],['explorer','Explorer'],['engagement','Engagement'],['modules','Modules'],['platform','Platform'],['billing','Billing & RTM'],['audit','Audit Activity']];return [['billing','Billing Review'],['overview','Monthly Summary']]}
function shell(){return `<div class="shell"><aside class="sidebar"><div class="side-brand"><span class="brand-glyph">✦</span><span><strong>REFLECT</strong><small>Provider Dashboard · V20</small></span></div><div class="user-card"><b>${esc(state.user.display_name)}</b><small>${esc(state.user.role)}${state.user.provider_id?' · '+esc(state.user.provider_id):''}</small></div><nav class="nav">${navItems().map(([id,label])=>`<button data-nav="${id}" class="${state.page===id?'active':''}"><span>${label}</span></button>`).join('')}</nav><div class="side-footer" id="datasetBadge">V18.2 billing-master dataset</div></aside><section class="workspace"><header class="topbar"><span class="crumb" id="crumb">Dashboard</span><div class="top-actions"><button class="btn hide-mobile" id="askBtn">Ask Reflect</button><button class="btn" id="settingsBtn">Display</button><button class="btn" id="logoutBtn">Sign out</button></div></header><main class="page" id="page"></main></section></div><div id="drawer"></div><div id="chat"></div><div id="modal"></div>`}
async function boot(){const m=await api('/api/months');state.months=m.months;state.month=m.default;if(state.user.role==='Provider')state.page='patients';else if(state.user.role==='Billing')state.page='billing';else state.page='overview';$('#app').innerHTML=shell();bindShell();const h=await api('/api/health');$('#datasetBadge').textContent=`${h.dataset==='full-v18.2'?'Full V18.2':'Sample V18.2'} · ${fmt(h.patients)} patients / ${fmt(h.providers)} providers`;await renderPage()}
function bindShell(){$$('[data-nav]').forEach(b=>b.onclick=async()=>{state.page=b.dataset.nav;state.patientsPage=1;$$('[data-nav]').forEach(x=>x.classList.toggle('active',x===b));await renderPage()});$('#logoutBtn').onclick=logout;$('#settingsBtn').onclick=settings;$('#askBtn').onclick=()=>openChat()}
function head(title,sub,extra=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="page-actions"><select id="monthSel">${state.months.map(m=>`<option ${m===state.month?'selected':''}>${m}</option>`).join('')}</select>${extra}</div></div>`}
function bindMonth(){const s=$('#monthSel');if(s)s.onchange=async()=>{state.month=s.value;state.patientsPage=1;if(state.patient){await openPatient(state.patient,true)}else await renderPage()}}
function kpi(label,val,sub=''){return `<div class="card kpi"><span>${label}</span><b>${val}</b><small>${sub}</small></div>`}
async function renderPage(){const p=$('#page');p.innerHTML=`${head('Loading…','Retrieving indexed monthly data')}<div class="skeleton"></div>`;try{if(state.page==='patients')await renderPatients();else if(state.page==='overview')await renderOverview();else if(state.page==='providerTime')await renderProviderTime();else if(state.page==='explorer')await renderExplorer();else if(state.page==='engagement')await renderEngagement();else if(state.page==='modules')await renderModulesAnalytics();else if(state.page==='platform')await renderPlatformAnalytics();else if(state.page==='review')await renderReview();else if(state.page==='providers')await renderProviders();else if(state.page==='audit')await renderAudit();else await renderBilling()}catch(e){p.innerHTML=`${head('Unable to load this view','The dashboard stopped the request instead of leaving the page in an endless loading state.')}<div class="error-panel"><b>Data request failed</b><p>${esc(e.message)}</p><button class="btn" id="retry">Retry</button></div>`;bindMonth();$('#retry').onclick=renderPage}}
async function renderPatients(){const p=$('#page');const d=await api(`/api/patients?month=${state.month}&page=${state.patientsPage}&page_size=25&search=${encodeURIComponent(state.patientsSearch)}&review=${state.patientsReview}&platform=${encodeURIComponent(state.patientsPlatform)}`);p.innerHTML=head(state.user.role==='Provider'?'My Patients':'Patient Directory',state.user.role==='Provider'?'Your assigned patient panel. Provider time is shown per patient and remains separate from patient engagement.':'Organization-level patient search and drill-down.')+`<div class="card"><div class="card-head"><div><h3>${fmt(d.total)} accessible patients</h3><p>Open a patient for Mobile/XR engagement, exact timestamps, provider activity timeline, and monthly billing-support evidence.</p></div><div class="filters"><input id="patientSearch" placeholder="Search patient ID" value="${esc(state.patientsSearch)}"><select id="platformFilter"><option value="">All platforms</option>${['Mobile Heavy','Mixed','XR Heavy'].map(x=>`<option ${state.patientsPlatform===x?'selected':''}>${x}</option>`).join('')}</select><select id="reviewFilter"><option value="">All workflow states</option><option value="1" ${state.patientsReview==='1'?'selected':''}>Review suggested</option><option value="0" ${state.patientsReview==='0'?'selected':''}>Routine</option></select><button class="btn" id="applyFilters">Apply</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Patient</th><th>Last activity</th><th>Sessions</th><th>Engagement min</th><th>Provider time</th><th>Completion</th><th>Platform</th><th>Pattern</th><th>Goal</th><th>Action</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td><button class="patient-link" data-patient="${r.patient_id}">${r.patient_id}</button></td><td>${date(r.last_activity_utc)}</td><td>${fmt(r.session_count)}</td><td>${fmt(r.total_minutes)}</td><td><b>${fmt(r.total_provider_minutes||0)} min</b><br><small>${fmt(r.data_review_minutes||0)} review · ${fmt(r.communication_minutes||0)} comm · ${fmt(r.documentation_minutes||0)} doc</small></td><td>${pct(r.completion_rate)}</td><td>${tag(r.platform_preference)}</td><td>${tag(r.trend_pattern,r.trend_pattern==='Decreasing'?'coral':'')}</td><td>${fmt(r.treatment_goal_progress)}%</td><td><button class="btn" data-patient="${r.patient_id}">Open profile</button></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>Page ${d.page} · showing ${d.rows.length} of ${fmt(d.total)}</span><div><button class="btn" id="prev" ${d.page<=1?'disabled':''}>Previous</button><button class="btn" id="next" ${(d.page*d.page_size)>=d.total?'disabled':''}>Next</button></div></div></div>`;bindMonth();$$('[data-patient]').forEach(b=>b.onclick=()=>openPatient(b.dataset.patient));$('#applyFilters').onclick=()=>{state.patientsSearch=$('#patientSearch').value.trim();state.patientsPlatform=$('#platformFilter').value;state.patientsReview=$('#reviewFilter').value;state.patientsPage=1;renderPatients()};$('#patientSearch').onkeydown=e=>{if(e.key==='Enter')$('#applyFilters').click()};$('#prev').onclick=()=>{state.patientsPage--;renderPatients()};$('#next').onclick=()=>{state.patientsPage++;renderPatients()}}
async function renderOverview(){
 const p=$('#page'),d=await api(`/api/overview?month=${state.month}`),m=d.month||{};
 if(state.user.role==='Provider'){
  const pr=d.provider||{};
  p.innerHTML=head('Provider Analytics','Panel-level context for the selected month. Use My Patients for the patient-specific evidence behind these patterns.')+
  `<div class="analytics-hero"><div><span class="eyebrow-inline">PANEL SNAPSHOT · ${state.month}</span><h2>${esc(pr.provider_display_name||'Provider panel')}</h2><p>${fmt(m.active_patients)} of ${fmt(pr.patient_count)} assigned patients were active. These metrics describe synthetic engagement and workflow activity only.</p></div><div class="hero-stat"><b>${fmt(m.active_rate)}%</b><span>active panel</span></div></div>`+
  `<div class="kpis">${kpi('Assigned patients',fmt(pr.patient_count),'current panel')}${kpi('Active this month',fmt(m.active_patients),`${fmt(m.active_rate)}% of panel`)}${kpi('Sessions',fmt(m.total_sessions),`${fmt(m.sessions_per_active)} / active patient`)}${kpi('Avg engagement',fmt(m.avg_engagement_index),'descriptive index')}${kpi('Avg completion',pct(m.avg_completion_rate),'session completion')}${kpi('Provider time',fmt(m.provider_time_total_provider_minutes||0)+' min',`${fmt(m.provider_time_data_review_minutes||0)} review · ${fmt(m.provider_time_communication_minutes||0)} comm · ${fmt(m.provider_time_documentation_minutes||0)} doc`)}</div>`+
  `<div class="analytics-grid"><div class="card chart-card"><div class="card-head"><div><h3>Engagement trajectory</h3><p>Monthly average engagement index for this provider panel.</p></div></div><div class="card-body">${svgLineChart(d.trend,[{key:'avg_engagement_index',label:'Engagement index'}],{min:0,max:100,suffix:''})}</div></div><div class="card chart-card"><div class="card-head"><div><h3>Active patients & sessions</h3><p>Panel activity volume across available billing months.</p></div></div><div class="card-body">${svgDualTrend(d.trend,'active_patients','total_sessions','Active patients','Sessions')}</div></div></div>`+
  `<div class="analytics-grid"><div class="card"><div class="card-head"><div><h3>Platform preference</h3><p>Assigned-patient platform mix.</p></div></div><div class="card-body">${donutSummary(d.platform_mix||[],'patients')}</div></div><div class="card"><div class="card-head"><div><h3>Engagement patterns</h3><p>Synthetic longitudinal behavior categories.</p></div></div><div class="card-body">${rankBars(d.engagement_patterns||[])}</div></div><div class="card"><div class="card-head"><div><h3>Time-of-day activity</h3><p>Patient sessions aggregated for ${state.month}.</p></div></div><div class="card-body">${rankBars(Object.entries(d.time_of_day||{}).map(([label,value])=>({label,value})))}</div></div></div>`+
  `<div class="card"><div class="card-head"><div><h3>Patients requiring review</h3><p>Workflow prioritization based on synthetic engagement/documentation signals; this is not a clinical risk score.</p></div><button class="btn" id="goPatients">Open patient list</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Patient</th><th>Last activity</th><th>Sessions</th><th>Engagement</th><th>Goal</th><th></th></tr></thead><tbody>${d.queue.map(r=>`<tr><td><b>${r.patient_id}</b></td><td>${date(r.last_activity_utc)}</td><td>${fmt(r.session_count)}</td><td>${fmt(r.engagement_index)}</td><td>${fmt(r.treatment_goal_progress)}%</td><td><button class="btn" data-patient="${r.patient_id}">Open</button></td></tr>`).join('')}</tbody></table></div></div>`;
  $('#goPatients').onclick=()=>{state.page='patients';renderPage()};$$('[data-patient]').forEach(b=>b.onclick=()=>openPatient(b.dataset.patient));
 }else if(state.user.role==='Admin'){
  p.innerHTML=head('Organization Analytics','Operational view across providers and patients. All values are synthetic and intended for dashboard demonstration.')+
  `<div class="analytics-hero admin-hero"><div><span class="eyebrow-inline">ORGANIZATION · ${state.month}</span><h2>Reflect engagement & provider operations</h2><p>${fmt(m.providers)} provider panels and ${fmt(m.patients)} patients are represented in this billing period. The view emphasizes activity, workload, and documentation readiness.</p></div><div class="hero-stat"><b>${fmt(m.active_rate)}%</b><span>patient active rate</span></div></div>`+
  `<div class="kpis admin-kpis">${kpi('Patients',fmt(m.patients),'organization population')}${kpi('Active patients',fmt(m.active_patients),`${fmt(m.active_rate)}% active`)}${kpi('Sessions',fmt(m.sessions),`${fmt(m.sessions_per_active)} / active patient`)}${kpi('Avg engagement',fmt(m.engagement),'descriptive index')}${kpi('Avg completion',pct(m.completion),'session completion')}${kpi('Review queue',fmt(m.review_suggested),`${fmt(m.review_rate)}% of active`)}${kpi('Provider time',fmt(m.provider_time_hours)+' hr','patient-specific total')}${kpi('Data review',fmt(m.review_hours)+' hr','provider review time')}${kpi('Communication',fmt(m.communication_hours)+' hr','provider communication')}${kpi('Documentation',fmt(m.documentation_hours)+' hr','provider documentation')}</div>`+
  `<div class="analytics-grid"><div class="card chart-card"><div class="card-head"><div><h3>Organization activity trend</h3><p>Active patients across all available months.</p></div></div><div class="card-body">${svgLineChart(d.trend,[{key:'active_patients',label:'Active patients'}],{})}</div></div><div class="card chart-card"><div class="card-head"><div><h3>Session volume trend</h3><p>Total Reflect XR + Mobile sessions by billing month.</p></div></div><div class="card-body">${svgLineChart(d.trend,[{key:'sessions',label:'Sessions'}],{})}</div></div></div>`+
  `<div class="analytics-grid"><div class="card"><div class="card-head"><div><h3>Provider engagement distribution</h3><p>Providers grouped by their average patient engagement index.</p></div></div><div class="card-body">${rankBars(d.engagement_bands||[])}</div></div><div class="card"><div class="card-head"><div><h3>Provider panel sizes</h3><p>Distribution of assigned-patient panel size.</p></div></div><div class="card-body">${rankBars(d.panel_bands||[])}</div></div><div class="card"><div class="card-head"><div><h3>Review workload</h3><p>Provider panels grouped by patients flagged for review.</p></div></div><div class="card-body">${rankBars(d.workload_bands||[])}</div></div></div>`+
  `<div class="analytics-grid wide-left"><div class="card"><div class="card-head"><div><h3>Regional operations</h3><p>Provider, patient, session, and review workload by synthetic region.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Region</th><th>Providers</th><th>Patients</th><th>Active</th><th>Active rate</th><th>Sessions</th><th>Review queue</th><th>Engagement</th></tr></thead><tbody>${(d.regions||[]).map(r=>`<tr><td><b>${esc(r.region)}</b></td><td>${fmt(r.providers)}</td><td>${fmt(r.patients)}</td><td>${fmt(r.active_patients)}</td><td>${fmt((r.active_patients/Math.max(r.patients,1))*100)}%</td><td>${fmt(r.sessions)}</td><td>${fmt(r.review_suggested)}</td><td>${fmt(r.engagement)}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-head"><div><h3>Operational interpretation</h3><p>Descriptive signals for admin review.</p></div></div><div class="card-body insight-stack">${adminInsight(m,d)}</div></div></div>`+
  `<div class="card"><div class="card-head"><div><h3>Largest provider panels</h3><p>Use this table to identify high-volume panels and compare operational workload.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Provider</th><th>Region</th><th>Patients</th><th>Active</th><th>Review queue</th><th>Sessions</th><th>Completion</th><th>Engagement</th><th>Total provider min</th></tr></thead><tbody>${(d.top_providers||[]).map(r=>`<tr><td><b>${r.provider_id||r.provider_key}</b><br><small>${esc(r.provider_display_name||'')}</small></td><td>${esc(r.region_code||'—')}</td><td>${fmt(r.patient_count)}</td><td>${fmt(r.active_patients)}</td><td>${fmt(r.review_suggested_patients)}</td><td>${fmt(r.total_sessions)}</td><td>${pct(r.avg_completion_rate)}</td><td>${fmt(r.avg_engagement_index)}</td><td><b>${fmt(r.total_provider_minutes||0)}</b></td></tr>`).join('')}</tbody></table></div></div>`;
 }else{
  p.innerHTML=head('Billing Summary','Organization context. Patient-specific provider time remains the billing-support unit.')+`<div class="kpis">${kpi('Patients',fmt(m.patients))}${kpi('Total provider time',fmt(m.total_provider_minutes)+' min')}${kpi('Data review',fmt(m.data_review_minutes)+' min')}${kpi('Communication',fmt(m.provider_communication_minutes)+' min')}${kpi('Documentation',fmt(m.documentation_minutes)+' min')}</div>`;
 }
 bindMonth();
}
function chartEmpty(){return '<div class="chart-empty">No data available for the selected period.</div>'}
function svgLineChart(rows,series,opt={}){if(!rows?.length)return chartEmpty();const W=720,H=230,P=34;let vals=[];series.forEach(s=>rows.forEach(r=>vals.push(Number(r[s.key]||0))));let min=opt.min??Math.min(...vals,0),max=opt.max??Math.max(...vals,1);if(max<=min)max=min+1;const x=i=>P+(W-P*2)*(rows.length===1?.5:i/(rows.length-1));const y=v=>H-P-(H-P*2)*(Number(v)-min)/(max-min);const grid=[0,.25,.5,.75,1].map(t=>`<line x1="${P}" y1="${P+(H-P*2)*t}" x2="${W-P}" y2="${P+(H-P*2)*t}" class="chart-grid"/>`).join('');const paths=series.map((s,si)=>{const pts=rows.map((r,i)=>`${x(i)},${y(r[s.key]||0)}`).join(' ');const dots=rows.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r[s.key]||0)}" r="3" class="series-${si}"/>`).join('');return `<polyline points="${pts}" class="chart-line series-${si}"/>${dots}`}).join('');const labels=rows.map((r,i)=>`<text x="${x(i)}" y="${H-8}" class="chart-label" text-anchor="middle">${String(r.month||'').slice(5)}</text>`).join('');return `<div class="svg-chart"><svg viewBox="0 0 ${W} ${H}" role="img">${grid}${paths}${labels}</svg><div class="chart-legend">${series.map((s,i)=>`<span><i class="legend-dot series-${i}"></i>${esc(s.label)}</span>`).join('')}</div></div>`}
function svgDualTrend(rows,a,b,la,lb){if(!rows?.length)return chartEmpty();const normalize=(key)=>{const mx=Math.max(...rows.map(r=>Number(r[key]||0)),1);return rows.map(r=>({...r,_v:Number(r[key]||0)/mx*100}))};const aa=normalize(a),bb=normalize(b),merged=rows.map((r,i)=>({month:r.month,a:aa[i]._v,b:bb[i]._v}));return svgLineChart(merged,[{key:'a',label:la},{key:'b',label:lb}],{min:0,max:100})+`<p class="chart-foot">Lines are normalized to each metric's monthly maximum so volume patterns can be compared without implying the same unit.</p>`}
function rankBars(rows){if(!rows?.length)return chartEmpty();const max=Math.max(...rows.map(r=>Number(r.value||0)),1);return `<div class="rank-bars">${rows.map(r=>`<div class="rank-row"><div class="rank-label"><span>${esc(r.label)}</span><b>${fmt(r.value)}</b></div><div class="rank-track"><i style="width:${Math.max(2,Number(r.value||0)/max*100)}%"></i></div></div>`).join('')}</div>`}
function donutSummary(rows,unit=''){if(!rows?.length)return chartEmpty();const total=rows.reduce((a,r)=>a+Number(r.value||0),0)||1;let acc=0;const palette=['#1F305E','#FF8282','#E8A33D','#586F8A'];const stops=rows.map((r,i)=>{const a=acc/total*360;acc+=Number(r.value||0);const b=acc/total*360;return `${palette[i%palette.length]} ${a}deg ${b}deg`}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${stops})"><div><b>${fmt(total)}</b><span>${esc(unit)}</span></div></div><div class="donut-legend">${rows.map((r,i)=>`<div><i style="background:${palette[i%palette.length]}"></i><span>${esc(r.label)}</span><b>${fmt(r.value)} · ${fmt(Number(r.value||0)/total*100)}%</b></div>`).join('')}</div></div>`}
function adminInsight(m,d){const active=Number(m.active_rate||0),review=Number(m.review_rate||0),eng=Number(m.engagement||0);return `<div class="insight-item"><span>Patient activity</span><b>${fmt(active)}% active in ${state.month}</b><p>${fmt(m.active_patients)} patients recorded at least one session in the selected month.</p></div><div class="insight-item"><span>Provider workload</span><b>${fmt(m.review_hours)} review hours documented</b><p>${fmt(m.review_suggested)} patients are in the synthetic review queue (${fmt(review)}% of active patients).</p></div><div class="insight-item"><span>Engagement context</span><b>Average index ${fmt(eng)}</b><p>Use provider and patient drill-downs to understand the distribution; this value is descriptive and not a clinical score.</p></div>`}

async function renderProviderTime(){const p=$('#page'),d=await api(`/api/provider-time?month=${state.month}`);if(!d.available){p.innerHTML=head('Provider Time','The V16.1 provider-time layer has not been prepared for this dataset.')+`<div class="error-panel"><b>Provider-time data unavailable</b><p>Run the V16.1/V20 data preparation step, then reload this page.</p></div>`;bindMonth();return}const k=d.kpis||{},isProvider=state.user.role==='Provider';const total=Number(k.total_provider_minutes||0),review=Number(k.data_review_minutes||0),comm=Number(k.communication_minutes||0),doc=Number(k.documentation_minutes||0),patients=Number(k.patients_with_provider_activity||0);p.innerHTML=head('Provider Time',isProvider?'Patient-specific provider work tracked separately from patient application engagement.':'Organization-level provider workload derived from patient-specific review, communication, and documentation records.')+`<div class="callout"><b>V20 time boundary</b><p>Provider time = data review + communication + documentation for a specific patient. Patient session duration and patient engagement minutes are never added to provider time.</p></div><div style="height:.8rem"></div><div class="kpis">${kpi('Total provider time',`${fmt(total)} min`,`${fmt(total/60)} hr in ${state.month}`)}${kpi('Data review',`${fmt(review)} min`,`${fmt(k.data_review_count||0)} activities`)}${kpi('Communication',`${fmt(comm)} min`,`${fmt(k.communication_count||0)} activities`)}${kpi('Documentation',`${fmt(doc)} min`,`${fmt(k.documentation_count||0)} activities`)}${kpi('Patients with activity',fmt(patients),'patient-specific records')}</div><div class="analytics-grid"><div class="card"><div class="card-head"><div><span class="eyebrow-inline">ACTIVITY MIX</span><h3>Where provider time was spent</h3><p>Review, communication, and documentation remain separate.</p></div></div><div class="card-body">${donutSummary(d.activity_mix||[],'minutes')}</div></div><div class="card chart-card"><div class="card-head"><div><span class="eyebrow-inline">12-MONTH TREND</span><h3>Provider-time trajectory</h3><p>Monthly patient-specific provider workload.</p></div></div><div class="card-body">${svgLineChart(d.trend||[],[{key:'data_review_minutes',label:'Data review'},{key:'communication_minutes',label:'Communication'},{key:'documentation_minutes',label:'Documentation'},{key:'total_provider_minutes',label:'Total'}],{})}</div></div></div><div class="analytics-grid"><div class="card"><div class="card-head"><div><h3>${isProvider?'Patient activity intensity':'Provider workload distribution'}</h3><p>${isProvider?'Patients grouped by generated provider-activity intensity.':'Providers grouped by monthly total provider time.'}</p></div></div><div class="card-body">${rankBars(d.intensity||[])}</div></div><div class="card"><div class="card-head"><div><h3>Interpretation</h3><p>Use this page as workload context, then drill down to one patient for the auditable timeline.</p></div></div><div class="card-body insight-stack"><div class="insight-item"><span>Billing-support unit</span><b>Provider → Patient → Month</b><p>V20 keeps each patient's provider time independent from every other patient.</p></div><div class="insight-item"><span>Patient engagement</span><b>Evidence being monitored, not provider time</b><p>Mobile/XR session duration remains visible in the patient workspace but is never added to provider activity minutes.</p></div></div></div></div>${isProvider?`<div class="card"><div class="card-head"><div><h3>Patients with the most provider activity</h3><p>Open a patient to inspect exact review, communication, and documentation timestamps.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Patient</th><th>Total provider min</th><th>Review</th><th>Communication</th><th>Documentation</th><th>Intensity</th><th>Action</th></tr></thead><tbody>${(d.top_patients||[]).map(r=>`<tr><td><b>${r.patient_id}</b></td><td>${fmt(r.total_provider_minutes)}</td><td>${fmt(r.data_review_minutes)}</td><td>${fmt(r.communication_minutes)}</td><td>${fmt(r.documentation_minutes)}</td><td>${tag(r.provider_activity_intensity||'—')}</td><td><button class="btn" data-time-patient="${r.patient_id}">Open profile</button></td></tr>`).join('')}</tbody></table></div></div>`:`<div class="card"><div class="card-head"><div><h3>Highest provider-time workloads</h3><p>Organization context only; patient-specific billing evidence remains patient-level.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Provider</th><th>Region</th><th>Patients with activity</th><th>Review min</th><th>Communication min</th><th>Documentation min</th><th>Total min</th></tr></thead><tbody>${(d.top_providers||[]).map(r=>`<tr><td><b>${r.provider_id||r.provider_key}</b><br><small>${esc(r.provider_display_name||'')}</small></td><td>${r.region_code||'—'}</td><td>${fmt(r.patients_with_provider_activity)}</td><td>${fmt(r.data_review_minutes)}</td><td>${fmt(r.communication_minutes)}</td><td>${fmt(r.documentation_minutes)}</td><td><b>${fmt(r.total_provider_minutes)}</b></td></tr>`).join('')}</tbody></table></div></div>`}`;bindMonth();$$('[data-time-patient]').forEach(b=>b.onclick=()=>openPatient(b.dataset.timePatient))}

async function renderReview(){state.patientsReview='1';state.patientsPage=1;await renderPatients();$('#page .page-head h1').textContent='Review Queue';$('#page .page-head p').textContent='Patients prioritized by the synthetic workflow flag. Open a patient for the evidence behind the flag.'}
async function renderProviders(){const p=$('#page');const d=await api('/api/providers?page=1');p.innerHTML=head('Providers','Administrator-only provider panels from the synthetic dataset.')+`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Provider</th><th>Region</th><th>Patients</th><th>Engagement</th><th>Completion propensity</th><th>XR probability</th><th>Remote probability</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td><b>${r.provider_id}</b><br><small>${esc(r.provider_display_name)}</small></td><td>${r.region_code}</td><td>${fmt(r.patient_count)}</td><td>${fmt(r.avg_engagement_baseline)}</td><td>${pct(r.avg_completion_propensity*100)}</td><td>${pct(r.avg_xr_probability*100)}</td><td>${pct(r.avg_remote_probability*100)}</td></tr>`).join('')}</tbody></table></div></div>`;bindMonth()}
async function renderAudit(){const p=$('#page');const d=await api('/api/audit');p.innerHTML=head('Audit Activity','Recent demo access and workflow actions.')+`<div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Time (UTC)</th><th>Role</th><th>Provider</th><th>Action</th><th>Patient key</th><th>Month</th><th>Detail</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${r.event_time_utc}</td><td>${r.role}</td><td>${r.provider_id||'—'}</td><td>${r.action}</td><td>${r.patient_key||'—'}</td><td>${r.billing_month||'—'}</td><td>${esc(r.detail||'')}</td></tr>`).join('')}</tbody></table></div></div>`;bindMonth()}
async function renderBilling(){const p=$('#page');const d=await api(`/api/overview?month=${state.month}`),m=d.month||{};if(state.user.role==='Billing'){const q=await api(`/api/billing/queue?month=${state.month}&page=1`);p.innerHTML=head('Billing Review','Patient-specific provider-time evidence for the selected monthly period.')+`<div class="callout"><b>Billing-support boundary</b><p>The evidence unit is one provider + one patient + one month. Patient engagement minutes are monitoring context and are never counted as provider time. Coding, coverage, medical necessity, and reimbursement require human review.</p></div><div style="height:.8rem"></div><div class="kpis">${kpi('Patient evidence records',fmt(q.total),'patients with provider activity')}${kpi('Total provider time',`${fmt(m.total_provider_minutes||0)} min`,'organization documentation context')}${kpi('Data review',`${fmt(m.data_review_minutes||0)} min`)}${kpi('Communication',`${fmt(m.provider_communication_minutes||0)} min`)}${kpi('Documentation',`${fmt(m.documentation_minutes||0)} min`)}</div><div class="card"><div class="card-head"><div><h3>Patient-specific monthly evidence queue</h3><p>Each row remains independently attributable to one patient.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Patient</th><th>Provider</th><th>Total provider min</th><th>Data review</th><th>Communication</th><th>Documentation</th><th>Remote sessions</th><th>Report</th></tr></thead><tbody>${q.rows.map(r=>`<tr><td><b>${r.patient_id}</b></td><td>${r.provider_id}<br><small>${esc(r.provider_display_name||'')}</small></td><td><b>${fmt(r.total_provider_minutes)}</b></td><td>${fmt(r.data_review_minutes)} min · ${fmt(r.data_review_count)} events</td><td>${fmt(r.communication_minutes)} min · ${fmt(r.communication_count)} events</td><td>${fmt(r.documentation_minutes)} min · ${fmt(r.documentation_count)} events</td><td>${fmt(r.remote_sessions)}</td><td><a class="btn" target="_blank" href="/api/billing/report?patient_id=${r.patient_id}&month=${state.month}">PDF</a></td></tr>`).join('')}</tbody></table></div></div>`;bindMonth();return}const total=Number(m.provider_time_total_provider_minutes??m.total_provider_minutes??0),review=Number(m.provider_time_data_review_minutes??m.data_review_minutes??0),comm=Number(m.provider_time_communication_minutes??m.provider_communication_minutes??0),doc=Number(m.provider_time_documentation_minutes??m.documentation_minutes??0);p.innerHTML=head('Billing & RTM Documentation','V20 centers billing-support evidence on provider time for each individual patient.')+`<div class="callout"><b>Core rule</b><p>Data review + communication + documentation = provider time. Patient session duration and engagement minutes remain separate monitoring evidence.</p></div><div style="height:.8rem"></div><div class="kpis">${kpi('Provider time',`${fmt(total)} min`,'workload context only')}${kpi('Data review',`${fmt(review)} min`)}${kpi('Communication',`${fmt(comm)} min`)}${kpi('Documentation',`${fmt(doc)} min`)}${kpi('Review suggested',fmt(m.review_suggested||m.review_suggested_patients||0),'workflow marker')}</div>${state.user.role==='Provider'?`<div class="card"><div class="card-head"><div><h3>Generate billing-support evidence from a patient profile</h3><p>Open one assigned patient, select the billing month, inspect the provider timeline, then download that patient’s monthly PDF.</p></div></div><div class="card-body"><button class="btn btn-primary" id="toPatients">Open My Patients</button><button class="btn" id="toProviderTime">Review Provider Time</button></div></div>`:`<div class="card"><div class="card-body"><p>Administrator totals are operational context only. Patient-specific reports remain the billing-support evidence unit.</p><button class="btn" id="toProviderTime">Open Provider Time Analytics</button></div></div>`}`;bindMonth();if($('#toPatients'))$('#toPatients').onclick=()=>{state.page='patients';renderPage()};if($('#toProviderTime'))$('#toProviderTime').onclick=()=>{state.page='providerTime';renderPage()}}
async function openPatient(id,keepTab=false){try{state.patient=id;state.patientData=null;if(!keepTab)state.patientTab='Summary';$('#drawer').innerHTML=`<div class="drawer-back"><aside class="drawer"><div class="drawer-head"><div><h2>${id}</h2><p>Loading patient-specific analytics…</p></div><button class="close" id="closeDrawer">×</button></div><div class="drawer-body"><div class="skeleton"></div></div></aside></div>`;$('#closeDrawer').onclick=closePatient;state.patientData=await api(`/api/patients/${id}?month=${state.month}`);renderPatient()}catch(e){$('#drawer').innerHTML=`<div class="drawer-back"><aside class="drawer"><div class="drawer-head patient-drawer-head"><div><span class="eyebrow-inline">PATIENT WORKSPACE</span><h2>${id}</h2><p>Patient analytics could not be prepared for ${state.month}.</p></div><button class="close" id="closeDrawer">×</button></div><div class="drawer-body"><div class="patient-error-card"><h3>Patient detail unavailable</h3><p>The dashboard stopped this request safely instead of showing incomplete analytics. V20 automatically creates and repairs the runtime detail tables at startup.</p><button class="btn btn-primary" id="retryPatient">Retry patient analytics</button><details><summary>Technical detail</summary><code>${esc(e.message)}</code></details></div></div></aside></div>`;$('#closeDrawer').onclick=closePatient;$('#retryPatient').onclick=()=>openPatient(id,true)}}
function renderPatient(){const d=state.patientData,p=d.patient,m=d.month_summary;const tabs=['Summary','Reflect Mobile','Reflect XR','Monthly Activity','Provider Activity','Communication','Billing','Insights'];$('#drawer').innerHTML=`<div class="drawer-back"><aside class="drawer"><div class="drawer-head patient-drawer-head"><div><span class="eyebrow-inline">PATIENT WORKSPACE · ${state.month}</span><h2>${p.patient_id}</h2><p>${d.provider.provider_display_name}</p><div class="patient-head-tags">${tag(p.platform_preference,'coral')}${tag(p.trend_pattern)}${tag(p.preferred_time_band)}${tag(d.goal.title)}</div></div><button class="close" id="closeDrawer">×</button></div><div class="tabs">${tabs.map(x=>`<button data-tab="${x}" class="${state.patientTab===x?'active':''}">${x}</button>`).join('')}</div><div class="drawer-body" id="patientBody"></div></aside></div>`;$('#closeDrawer').onclick=closePatient;$$('[data-tab]').forEach(b=>b.onclick=()=>{state.patientTab=b.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderPatientTab()});renderPatientTab()}
function providerActivityTimeline(rows){if(!rows?.length)return '<p>No provider activity recorded for this patient/month.</p>';return `<div class="provider-timeline">${rows.map(a=>`<div class="provider-event ${String(a.activity_type||'').toLowerCase()}"><div class="event-time"><b>${esc(a.display_start||date(a.activity_start_utc))}</b><small>${esc(a.display_end||date(a.activity_end_utc))}</small></div><div class="event-dot"></div><div class="event-content"><div class="event-top"><b>${esc(String(a.activity_type||'').replaceAll('_',' '))}</b><span>${fmt(a.duration_minutes)} min</span></div><p>${esc(String(a.activity_subtype||'').replaceAll('_',' '))}${(a.review_focus||a.focus_area)?` · ${esc(a.review_focus||a.focus_area)}`:''}</p>${a.communication_channel?`<small>${esc(a.communication_channel)} · ${esc(a.interaction_mode||'')}</small>`:''}${a.note_text?`<small>${esc(a.note_text)}</small>`:''}</div></div>`).join('')}</div>`}
function providerDaily(rows){if(!rows?.length)return '<p>No daily provider activity recorded.</p>';return `<div class="table-wrap"><table class="table compact"><thead><tr><th>Date</th><th>Review</th><th>Communication</th><th>Documentation</th><th>Total</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.activity_date)}</td><td>${fmt(r.data_review_minutes)} min</td><td>${fmt(r.communication_minutes)} min</td><td>${fmt(r.documentation_minutes)} min</td><td><b>${fmt(r.total_provider_minutes)} min</b></td></tr>`).join('')}</tbody></table></div>`}
function renderPatientTab(){
 const d=state.patientData,p=d.patient,m=d.month_summary,b=d.billing||{},pt=d.provider_time||b,body=$('#patientBody');if(!body)return;
 const hist=d.history||[],ins=d.insights||{},acts=d.provider_activities||[],profile=d.provider_profile||{},delta=(v,label,suffix='')=>v===null||v===undefined?'':`<span class="delta ${v>0?'up':v<0?'down':'flat'}">${v>0?'+':''}${fmt(v)}${suffix} vs prior month ${label||''}</span>`;
 if(state.patientTab==='Summary')body.innerHTML=`<div class="patient-story"><div><span class="eyebrow-inline">PATIENT ENGAGEMENT STORY · ${state.month}</span><h2>Activity, engagement, and provider monitoring</h2><p>Patient engagement and provider activity are intentionally separated. Provider time is tracked only when the provider reviews, communicates about, or documents this specific patient.</p></div><div class="story-status">${tag(m.review_suggested?'Review suggested':'Routine review',m.review_suggested?'coral':'good')}</div></div><div class="kpis">${kpi('Sessions',fmt(m.session_count),delta(ins.session_change,'',''))}${kpi('Engagement min',fmt(m.total_minutes),'patient application time')}${kpi('Provider time',`${fmt(b.total_provider_minutes)} min`,'review + communication + documentation')}${kpi('Completion',pct(m.completion_rate),delta(ins.completion_change,'',' pp'))}${kpi('Active days',fmt(m.active_days),state.month)}</div><div class="provider-time-banner"><div><span>PROVIDER TIME FOR THIS PATIENT</span><b>${fmt(b.total_provider_minutes)} min</b><small>${fmt(b.data_review_minutes)} review · ${fmt(b.communication_minutes)} communication · ${fmt(b.documentation_minutes)} documentation</small></div><div><span>PATIENT ENGAGEMENT</span><b>${fmt(m.total_minutes)} min</b><small>${fmt(m.mobile_sessions)} Mobile · ${fmt(m.xr_sessions)} XR sessions</small></div><p>These timelines are separate. Patient engagement minutes are never counted as provider time.</p></div><div class="analytics-grid"><div class="card chart-card"><div class="card-head"><div><h3>Engagement & goal trajectory</h3><p>Month-over-month descriptive trend, 0-100 scale.</p></div></div><div class="card-body">${svgLineChart(hist,[{key:'engagement_index',label:'Engagement index'},{key:'treatment_goal_progress',label:'Goal progress'}],{min:0,max:100})}</div></div><div class="card chart-card"><div class="card-head"><div><h3>Mobile vs XR session trend</h3><p>Platform-specific session counts across available months.</p></div></div><div class="card-body">${stackedMonthBars(hist,'mobile_sessions','xr_sessions','Mobile','XR')}</div></div></div><div class="analytics-grid"><div class="card"><div class="card-head"><div><h3>Selected-month platform mix</h3><p>${fmt(m.session_count)} patient sessions in ${state.month}.</p></div></div><div class="card-body">${donutSummary([{label:'Mobile',value:m.mobile_sessions},{label:'XR',value:m.xr_sessions}],'sessions')}</div></div><div class="card"><div class="card-head"><div><h3>Remote vs in-clinic</h3><p>Session context is shown as monitoring evidence.</p></div></div><div class="card-body">${donutSummary([{label:'Remote',value:m.remote_sessions},{label:'In Clinic',value:m.clinic_sessions}],'sessions')}</div></div><div class="card"><div class="card-head"><div><h3>Treatment-goal monitoring</h3><p>Synthetic provider-defined goal context, not a clinical outcome.</p></div></div><div class="card-body"><h3>${esc(d.goal.title)}</h3><div class="progress"><i style="width:${Math.min(100,d.goal.progress_percent)}%"></i></div><p><b>${d.goal.progress_percent}%</b> generated progress for ${state.month}</p></div></div></div><div class="card"><div class="card-head"><div><h3>Descriptive engagement notes</h3><p>Automatically derived from the patient's synthetic activity; no diagnosis or treatment recommendation.</p></div></div><div class="card-body">${patientNarrative(d)}</div></div>`;
 if(state.patientTab==='Reflect Mobile')body.innerHTML=moduleView('Reflect Mobile',d.mobile_modules,14,'Official Mobile modules are shown separately. Use this view to understand exactly what this patient used during the selected month.');
 if(state.patientTab==='Reflect XR')body.innerHTML=moduleView('Reflect XR',d.xr_modules,17,'Official XR modules are shown separately from Mobile for clearer provider review.');
 if(state.patientTab==='Monthly Activity')body.innerHTML=`<div class="selected-month-strip"><div><span>Reflect Mobile</span><b>${fmt(m.mobile_sessions)}</b><small>sessions in ${state.month}</small></div><div><span>Reflect XR</span><b>${fmt(m.xr_sessions)}</b><small>sessions in ${state.month}</small></div><div><span>Total patient sessions</span><b>${fmt(m.session_count)}</b><small>${fmt(m.total_minutes)} engagement minutes</small></div></div><div class="analytics-grid"><div class="card chart-card"><div class="card-head"><div><h3>Time-of-day engagement</h3><p>Sessions grouped into four US Eastern periods.</p></div></div><div class="card-body">${rankBars(Object.entries(d.time_of_day).map(([label,value])=>({label,value})))}</div></div><div class="card chart-card"><div class="card-head"><div><h3>24-hour session pattern</h3><p>Exact patient session timestamps for ${state.month}.</p></div></div><div class="card-body">${hourBars(d.hourly)}</div></div></div><div class="analytics-grid"><div class="card chart-card"><div class="card-head"><div><h3>Monthly Mobile/XR volume</h3><p>How many times this patient used each platform in every available month.</p></div></div><div class="card-body">${stackedMonthBars(hist,'mobile_sessions','xr_sessions','Mobile','XR')}</div></div><div class="card chart-card"><div class="card-head"><div><h3>Monthly engagement minutes</h3><p>Patient application engagement time by month.</p></div></div><div class="card-body">${svgLineChart(hist,[{key:'total_minutes',label:'Patient engagement minutes'}],{})}</div></div></div><div class="card"><div class="card-head"><div><h3>Recent patient sessions</h3><p>Timestamp, platform, module, duration, context, and completion status.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Platform</th><th>Module</th><th>Duration</th><th>Context</th><th>Completed</th></tr></thead><tbody>${d.events.slice(0,50).map(e=>`<tr><td>${e.display_start}</td><td>${tag(e.platform,e.platform==='XR'?'':'coral')}</td><td>${esc(e.module_name)}</td><td>${fmt(e.duration_minutes)} min</td><td>${tag(e.remote_or_clinic,e.remote_or_clinic==='Remote'?'good':'')}</td><td>${e.completed?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div></div>`;
 if(state.patientTab==='Provider Activity')body.innerHTML=`<div class="provider-time-hero"><div><span class="eyebrow-inline">PATIENT-SPECIFIC PROVIDER TIME · ${state.month}</span><h2>${fmt(b.total_provider_minutes)} minutes</h2><p>Only provider work performed for ${p.patient_id}. Patient engagement duration is excluded.</p></div><div class="provider-time-equation"><div><span>Data review</span><b>${fmt(b.data_review_minutes)}</b><small>${fmt(b.data_review_count)} activities</small></div><i>+</i><div><span>Communication</span><b>${fmt(b.communication_minutes)}</b><small>${fmt(b.communication_count)} activities</small></div><i>+</i><div><span>Documentation</span><b>${fmt(b.documentation_minutes)}</b><small>${fmt(b.documentation_count)} activities</small></div><i>=</i><div class="total"><span>Total</span><b>${fmt(b.total_provider_minutes)}</b><small>provider minutes</small></div></div></div><div class="analytics-grid"><div class="review-box"><span class="tag coral">LIVE DATA REVIEW</span><h3>Track time reviewing this patient</h3><p>Start the timer only while reviewing ${p.patient_id}'s dashboard data.</p>${state.review?`<div class="review-clock" id="reviewClock">${reviewClock()}</div><button class="btn btn-primary" id="endReview">End & record data review</button>`:`<button class="btn btn-primary" id="startReview">Start patient data review</button>`}</div><div class="card chart-card"><div class="card-head"><div><h3>Total provider time trend</h3><p>Review + communication + documentation by month for this patient.</p></div></div><div class="card-body">${svgLineChart(hist,[{key:'data_review_minutes',label:'Data review'},{key:'provider_communication_minutes',label:'Communication'},{key:'documentation_minutes',label:'Documentation'},{key:'total_provider_minutes',label:'Total provider time'}],{})}</div></div></div><div class="analytics-grid"><div class="card"><div class="card-head"><div><h3>Provider work profile</h3><p>Synthetic stable behavior profile used to generate realistic activity timing.</p></div></div><div class="card-body profile-grid"><div><span>Review style</span><b>${esc(profile.review_style||'—')}</b></div><div><span>Work window</span><b>${esc(profile.preferred_work_window||'—')}</b></div><div><span>Communication</span><b>${esc(profile.communication_preference||'—')}</b></div><div><span>Documentation</span><b>${esc(profile.documentation_cadence||'—')}</b></div><div><span>Review focus</span><b>${esc(profile.review_focus_preference||'—')}</b></div></div></div><div class="card"><div class="card-head"><div><h3>Add documentation</h3><p>Documentation time is tracked as provider time for this patient.</p></div></div><div class="card-body"><div class="form-stack"><label class="field"><span>Documentation minutes</span><input id="noteDuration" type="number" min="0.1" step="0.1" value="3"></label><textarea id="noteText" placeholder="Document the provider note…"></textarea><button class="btn" id="saveNote">Save documentation</button></div><div class="timeline">${d.notes.map(n=>`<div class="timeline-item"><span>${date(n.created_at_utc)}</span><span>${esc(n.note_text)}</span><span>${fmt(n.documentation_minutes||0)} min</span></div>`).join('')||'<p>No V20 documentation notes recorded.</p>'}</div></div></div></div><div class="card"><div class="card-head"><div><h3>Daily provider-time summary</h3><p>Auditable daily reconciliation for this patient and month.</p></div></div><div class="card-body">${providerDaily(d.provider_daily||[])}</div></div><div class="card"><div class="card-head"><div><h3>Detailed provider timeline</h3><p>Review, communication, and documentation events with exact timestamps.</p></div></div><div class="card-body">${providerActivityTimeline(acts)}</div></div>`;
 if(state.patientTab==='Communication'){const commActs=acts.filter(a=>a.activity_type==='COMMUNICATION');body.innerHTML=`<div class="analytics-grid"><div class="card"><div class="card-head"><div><h3>Document communication</h3><p>The interaction may occur outside Reflect. The recorded duration becomes provider time for this patient.</p></div></div><div class="card-body form-stack"><div class="form-row"><label class="field"><span>Mode</span><select id="commMode"><option>Asynchronous</option><option>Real-time interactive</option></select></label><label class="field"><span>Channel</span><select id="commChannel"><option>Portal Message</option><option>Secure Message</option><option>Phone</option><option>Video</option><option>Email</option><option>Outside Reflect</option></select></label></div><label class="field"><span>Provider time (minutes)</span><input id="commDuration" type="number" min="0.1" step="0.1" value="5"></label><label class="field"><span>Summary</span><textarea id="commSummary" placeholder="Document the interaction…"></textarea></label><button class="btn btn-primary" id="saveComm">Record communication</button></div></div><div class="card chart-card"><div class="card-head"><div><h3>Communication minutes by month</h3><p>Patient-specific provider communication time.</p></div></div><div class="card-body">${svgLineChart(hist,[{key:'provider_communication_minutes',label:'Communication minutes'}],{})}</div></div></div><div class="card"><div class="card-head"><h3>Communication timeline</h3></div><div class="card-body">${providerActivityTimeline(commActs)}</div></div>`}
 if(state.patientTab==='Billing')body.innerHTML=`<div class="report-preview v17-report"><div class="report-brand"><span class="brand-glyph">✦</span><div><b>REFLECT</b><small>PATIENT-SPECIFIC PROVIDER TIME & DOCUMENTATION SUPPORT</small></div><span class="tag amber">REQUIRES_REVIEW</span></div><div class="report-title"><span>Patient ${p.patient_id} · Provider ${d.provider.provider_id}</span><h2>${state.month} provider-time evidence</h2><p>The primary evidence is provider work performed for this patient. Patient application engagement is supporting monitoring context and is not counted as provider time.</p></div><div class="provider-time-equation report-equation"><div><span>Data review</span><b>${fmt(b.data_review_minutes)}</b><small>minutes</small></div><i>+</i><div><span>Communication</span><b>${fmt(b.communication_minutes)}</b><small>minutes</small></div><i>+</i><div><span>Documentation</span><b>${fmt(b.documentation_minutes)}</b><small>minutes</small></div><i>=</i><div class="total"><span>Total provider time</span><b>${fmt(b.total_provider_minutes)}</b><small>minutes for ${p.patient_id}</small></div></div><div class="report-sections"><div><h4>Provider activity</h4><p>${fmt(b.data_review_count)} data reviews · ${fmt(b.communication_count)} communications · ${fmt(b.documentation_count)} documentation activities.</p></div><div><h4>Patient engagement being monitored</h4><p>${fmt(m.session_count)} sessions · ${fmt(m.total_minutes)} patient engagement minutes · ${fmt(m.mobile_sessions)} Mobile · ${fmt(m.xr_sessions)} XR.</p></div><div><h4>Remote monitoring context</h4><p>${fmt(b.remote_sessions)} remote sessions across ${fmt(b.remote_active_days)} remote-active days.</p></div><div><h4>Compliance boundary</h4><p>Documentation support only; no automatic coding, coverage, medical necessity, or reimbursement determination.</p></div></div><a class="btn btn-primary report-download" target="_blank" href="/api/billing/report?patient_id=${p.patient_id}&month=${state.month}">Download V20 branded monthly PDF</a></div>`;
 if(state.patientTab==='Insights')body.innerHTML=`<div class="analytics-grid"><div class="card"><div class="card-head"><div><h3>Ask Reflect — patient context</h3><p>Patient-specific descriptive assistant.</p></div></div><div class="card-body"><p>Ask Reflect is locked to <b>${p.patient_id}</b> and ${state.month}. It can summarize patient engagement and explain this patient's provider-time evidence without making a diagnosis or billing decision.</p><button class="btn btn-primary" id="openAsk">Open Ask Reflect</button></div></div><div class="card"><div class="card-head"><div><h3>Current-month analytics snapshot</h3><p>Patient activity and provider activity are deliberately separated.</p></div></div><div class="card-body">${patientNarrative(d)}<div class="insight-item"><span>Provider time</span><b>${fmt(b.total_provider_minutes)} min for ${p.patient_id}</b><p>${fmt(b.data_review_minutes)} review + ${fmt(b.communication_minutes)} communication + ${fmt(b.documentation_minutes)} documentation.</p></div></div></div></div>`;
 $('#startReview')?.addEventListener('click',startReview);$('#endReview')?.addEventListener('click',endReview);$('#saveNote')?.addEventListener('click',saveNote);$('#saveComm')?.addEventListener('click',saveComm);$('#openAsk')?.addEventListener('click',()=>openChat());
}

function stackedMonthBars(rows,a,b,la,lb){if(!rows?.length)return chartEmpty();const max=Math.max(...rows.map(r=>Number(r[a]||0)+Number(r[b]||0)),1);return `<div class="stack-chart">${rows.map(r=>{const av=Number(r[a]||0),bv=Number(r[b]||0),tot=av+bv;return `<div class="stack-col" title="${r.month}: ${la} ${av}, ${lb} ${bv}"><div class="stack-bar"><i class="stack-a" style="height:${av/max*100}%"></i><i class="stack-b" style="height:${bv/max*100}%"></i></div><span>${r.month.slice(5)}</span></div>`}).join('')}</div><div class="chart-legend"><span><i class="legend-dot stack-a"></i>${la}</span><span><i class="legend-dot stack-b"></i>${lb}</span></div>`}
function patientNarrative(d){const m=d.month_summary||{},i=d.insights||{},tod=d.time_of_day||{},peak=Object.entries(tod).sort((a,b)=>b[1]-a[1])[0]||['—',0],mods=[...(d.mobile_modules||[]),...(d.xr_modules||[])].sort((a,b)=>b.sessions-a.sessions),top=mods[0];const change=i.engagement_change==null?'No prior-month comparison is available.':`Engagement index ${i.engagement_change>0?'increased':i.engagement_change<0?'decreased':'was unchanged'} by ${Math.abs(i.engagement_change)} points from the prior month.`;return `<div class="insight-stack"><div class="insight-item"><span>Monthly change</span><b>${change}</b><p>${i.session_change==null?'':`${i.session_change>=0?'+':''}${i.session_change} sessions versus the prior month.`}</p></div><div class="insight-item"><span>Timing pattern</span><b>${peak[0]} is the most active period</b><p>${fmt(peak[1])} sessions occurred in that time band.</p></div><div class="insight-item"><span>Most-used module</span><b>${top?esc(top.module_name):'No module activity'}</b><p>${top?`${top.sessions} sessions and ${fmt(top.minutes)} minutes in ${state.month}.`:'No sessions were materialized for the selected month.'}</p></div></div>`}

function simpleBars(items){return `<div class="bar-list">${items.map(([label,val,max])=>`<div class="bar-row"><span>${esc(label)}</span><div class="bar-track"><i class="bar-fill" style="width:${Math.min(100,(Number(val||0)/Math.max(Number(max||1),1))*100)}%"></i></div><b>${fmt(val)}</b></div>`).join('')}</div>`}
function hourBars(a){const max=Math.max(...a,1);return `<div class="trend-line">${a.map((v,i)=>`<div class="trend-col"><i style="height:${Math.max(3,v/max*100)}%"></i><span>${i%3===0?i:''}</span></div>`).join('')}</div>`}
function moduleView(title,rows,total,sub){const used=rows.reduce((a,r)=>a+r.sessions,0),mins=rows.reduce((a,r)=>a+Number(r.minutes||0),0),best=rows[0];return `<div class="page-head module-head"><div><span class="eyebrow-inline">PATIENT MODULE ANALYTICS · ${state.month}</span><h1>${title}</h1><p>${sub}</p></div><span class="tag">${rows.length} used / ${total} official modules</span></div><div class="kpis module-kpis">${kpi('Platform sessions',fmt(used))}${kpi('Engagement min',fmt(mins))}${kpi('Modules used',`${rows.length}/${total}`)}${kpi('Most used',best?esc(best.module_name):'—')}</div><div class="analytics-grid wide-left"><div class="card"><div class="card-head"><div><h3>Module usage ranking</h3><p>Sessions by module for this patient and month.</p></div></div><div class="card-body">${rankBars(rows.map(r=>({label:r.module_name,value:r.sessions})))}</div></div><div class="card"><div class="card-head"><div><h3>Platform interpretation</h3><p>Descriptive usage context.</p></div></div><div class="card-body insight-stack"><div class="insight-item"><span>Breadth</span><b>${rows.length} of ${total} modules used</b><p>Shows variety of module engagement, not clinical effectiveness.</p></div><div class="insight-item"><span>Depth</span><b>${fmt(mins)} minutes recorded</b><p>Total ${title} engagement in ${state.month}.</p></div>${best?`<div class="insight-item"><span>Most used</span><b>${esc(best.module_name)}</b><p>${best.sessions} sessions · ${fmt(best.minutes)} minutes · ${best.completion_rate}% completion.</p></div>`:''}</div></div></div><div class="module-grid">${rows.map(r=>`<div class="module-item"><div class="module-item-top"><div><h4>${esc(r.module_name)}</h4><small>${esc(r.program_group)} · Last ${r.last_activity_display}</small></div><span class="tag">${r.sessions} sessions</span></div><div class="module-stats"><div><span>Minutes</span><b>${fmt(r.minutes)}</b></div><div><span>Avg duration</span><b>${fmt(r.avg_duration)} min</b></div><div><span>Completion</span><b>${r.completion_rate}%</b></div></div></div>`).join('')||'<div class="callout">No activity for this platform in the selected month.</div>'}</div>`}

function analyticsKpis(d){const k=d.kpis||{};return `<div class="kpis analytics-six">${kpi('Cohort patients',fmt(k.cohort_patients||k.patients||0),'records in current scope')}${kpi('Sessions',fmt(k.sessions||0),'selected billing month')}${kpi('Avg duration',`${fmt(k.avg_duration||0)} min`,'per recorded session')}${kpi('Completion',pct(k.completion||0),'generated completion metric')}${kpi('Engagement',fmt(k.engagement||0),'descriptive index')}${kpi('Review suggested',fmt(k.review_suggested||0),'workflow marker')}</div>`}
function heatmapMatrix(rows){const es=['Low','Moderate','High','Very High'],cs=['Low <50%','Moderate 50-74%','High 75-89%','Very High 90%+'];const map={};let mx=1,total=0;(rows||[]).forEach(r=>{map[`${r.engagement_band}|${r.completion_band}`]=Number(r.value||0);mx=Math.max(mx,Number(r.value||0));total+=Number(r.value||0)});return `<div class="heatmap"><div></div>${cs.map(c=>`<b>${c}</b>`).join('')}${es.map(e=>`<span class="heat-y">${e}</span>${cs.map(c=>{const v=map[`${e}|${c}`]||0,a=.08+.72*(v/mx);return `<div class="heat-cell" style="background:rgba(31,48,94,${a.toFixed(3)})"><b>${fmt(v)}</b><small>${total?((v/total)*100).toFixed(1):0}%</small></div>`}).join('')}`).join('')}</div>`}
async function getAnalytics(){return await api(`/api/analytics?month=${state.month}`)}
async function renderExplorer(){const p=$('#page');const qs=new URLSearchParams({month:state.month,provider:state.explorerProvider,platform:state.explorerPlatform,pattern:state.explorerPattern,activity:state.explorerActivity});const d=await api(`/api/analytics/explorer?${qs}`);p.innerHTML=head('Exploratory Analytics','Build a descriptive cohort, then inspect engagement, platform, pattern, and recent activity mix.')+`<div class="card explorer-controls"><div class="explorer-grid">${state.user.role==='Admin'?`<label><span>Provider</span><input id="xProvider" placeholder="PRV-00001 (optional)" value="${esc(state.explorerProvider)}"></label>`:''}<label><span>Platform</span><select id="xPlatform"><option value="">All platforms</option>${['Mobile Heavy','Mixed','XR Heavy'].map(x=>`<option ${state.explorerPlatform===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span>Pattern</span><select id="xPattern"><option value="">All patterns</option>${['Increasing','Consistent','Decreasing','Intermittent'].map(x=>`<option ${state.explorerPattern===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span>Activity</span><select id="xActivity"><option value="">All activity</option><option value="active" ${state.explorerActivity==='active'?'selected':''}>Active</option><option value="inactive" ${state.explorerActivity==='inactive'?'selected':''}>Inactive</option></select></label></div><div class="explorer-actions"><button class="btn btn-primary" id="runExplore">Run exploration</button><button class="btn" id="resetExplore">Reset</button><span class="tag coral">Interactive cohort</span></div></div>${analyticsKpis(d)}<div class="visual-grid-three"><div class="card"><div class="card-head"><div><span class="eyebrow-inline">PLATFORM</span><h3>Platform mix</h3><p>Filtered cohort distribution.</p></div></div><div class="card-body">${donutSummary(d.platform_mix||[],'patients')}</div></div><div class="card"><div class="card-head"><div><span class="eyebrow-inline">PATTERN</span><h3>Engagement patterns</h3><p>Longitudinal synthetic pattern mix.</p></div></div><div class="card-body">${donutSummary(d.patterns||[],'patients')}</div></div><div class="card"><div class="card-head"><div><span class="eyebrow-inline">RECENCY</span><h3>Recent activity</h3><p>Session-volume classification for ${state.month}.</p></div></div><div class="card-body">${rankBars(d.activity||[])}</div></div></div>`;bindMonth();$('#runExplore').onclick=()=>{state.explorerProvider=$('#xProvider')?.value.trim()||'';state.explorerPlatform=$('#xPlatform').value;state.explorerPattern=$('#xPattern').value;state.explorerActivity=$('#xActivity').value;renderExplorer()};$('#resetExplore').onclick=()=>{state.explorerProvider=state.explorerPlatform=state.explorerPattern=state.explorerActivity='';renderExplorer()}}
async function renderEngagement(){const p=$('#page'),d=await getAnalytics();p.innerHTML=head('Engagement Analytics','Descriptive engagement, recency, completion, and monthly trend context. These are not clinical outcomes.')+`${analyticsKpis(d)}<div class="visual-grid-three"><div class="card"><div class="card-head"><div><span class="eyebrow-inline">PATTERN</span><h3>Engagement pattern mix</h3><p>Increasing, consistent, decreasing, and intermittent.</p></div></div><div class="card-body">${donutSummary(d.patterns||[],'patients')}</div></div><div class="card"><div class="card-head"><div><span class="eyebrow-inline">RECENCY</span><h3>Recent activity</h3><p>Current-month activity classification.</p></div></div><div class="card-body">${rankBars(d.activity||[])}</div></div><div class="card"><div class="card-head"><div><span class="eyebrow-inline">ENGAGEMENT</span><h3>Engagement profile</h3><p>Generated descriptive engagement index.</p></div></div><div class="card-body">${donutSummary(d.engagement_profile||[],'patients')}</div></div></div><div class="card"><div class="card-head"><div><span class="eyebrow-inline">COHORTS</span><h3>Engagement × completion</h3><p>Descriptive cohort matrix for provider context.</p></div></div><div class="card-body">${heatmapMatrix(d.matrix||[])}</div></div><div class="analytics-grid"><div class="card chart-card"><div class="card-head"><div><h3>Monthly engagement trend</h3><p>Average engagement index across available months.</p></div></div><div class="card-body">${svgLineChart(d.trend||[],[{key:'engagement',label:'Engagement index'}],{min:0,max:100})}</div></div><div class="card chart-card"><div class="card-head"><div><h3>Monthly session trend</h3><p>Session volume across the same scope.</p></div></div><div class="card-body">${svgLineChart(d.trend||[],[{key:'sessions',label:'Sessions'}],{})}</div></div></div>`;bindMonth()}
async function renderModulesAnalytics(){const p=$('#page'),d=await getAnalytics(),mob=d.mobile_modules||[],xr=d.xr_modules||[];p.innerHTML=head('Module Analytics','Reflect Mobile and Reflect XR are intentionally separated so usage is easy to interpret.')+`${analyticsKpis(d)}<div class="analytics-grid"><div class="card"><div class="card-head"><div><span class="eyebrow-inline">REFLECT MOBILE</span><h3>Mobile module activity</h3><p>Patients for whom each module was the top Mobile activity in ${state.month}.</p></div><span class="tag">14 official modules</span></div><div class="card-body">${rankBars(mob)}</div></div><div class="card"><div class="card-head"><div><span class="eyebrow-inline">REFLECT XR</span><h3>XR module activity</h3><p>Patients for whom each module was the top XR activity in ${state.month}.</p></div><span class="tag">17 official modules</span></div><div class="card-body">${rankBars(xr)}</div></div></div><div class="card"><div class="card-head"><div><h3>Module analytics interpretation</h3><p>Use module counts as engagement context, then open an individual patient for exact timestamps, duration, completion, and provider-review evidence.</p></div></div><div class="card-body insight-stack"><div class="insight-item"><span>Patient-first workflow</span><b>Population modules are context, not the billing record</b><p>The provider-specific patient profile remains the authoritative dashboard view for detailed monitoring.</p></div><div class="insight-item"><span>Separate products</span><b>Mobile and XR remain distinct</b><p>This prevents a provider from confusing app activity with headset activity.</p></div></div></div>`;bindMonth()}
async function renderPlatformAnalytics(){const p=$('#page'),d=await getAnalytics();p.innerHTML=head('Platform Analytics','Reflect XR and Reflect Mobile engagement patterns across the current scope.')+`${analyticsKpis(d)}<div class="analytics-grid wide-left"><div class="card"><div class="card-head"><div><span class="eyebrow-inline">PREFERENCE</span><h3>Platform preference</h3><p>Mobile Heavy, Mixed, and XR Heavy synthetic preference.</p></div></div><div class="card-body">${donutSummary(d.platform_mix||d.monthly_platform||[],'patients')}</div></div><div class="card platform-scale"><div><span class="eyebrow-inline">SCALE</span><h3>Platform-ready architecture</h3><p>Detailed events remain patient/month scoped so the browser never downloads the full population.</p><b>${fmt((d.kpis||{}).sessions||0)}</b><small>sessions represented in ${state.month}</small><div class="flow-pills"><span>Reflect XR</span><i>+</i><span>Reflect Mobile</span><i>→</i><span>Provider analytics</span></div></div></div></div><div class="analytics-grid"><div class="card"><div class="card-head"><div><h3>Time-of-day engagement</h3><p>Morning, afternoon, evening, and night usage.</p></div></div><div class="card-body">${rankBars(d.time_of_day||[])}</div></div><div class="card chart-card"><div class="card-head"><div><h3>Platform session trend</h3><p>Total session volume across available billing months.</p></div></div><div class="card-body">${svgLineChart(d.trend||[],[{key:'sessions',label:'Sessions'}],{})}</div></div></div>`;bindMonth()}

function reviewClock(){if(!state.reviewStarted)return'00:00';const s=Math.floor((Date.now()-state.reviewStarted)/1000),m=Math.floor(s/60);return `${String(m).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
async function startReview(){const d=await api('/api/reviews/start',{method:'POST',body:JSON.stringify({patient_id:state.patient,month:state.month})});state.review=d;state.reviewStarted=Date.now();clearInterval(state.reviewTimer);state.reviewTimer=setInterval(()=>{if($('#reviewClock'))$('#reviewClock').textContent=reviewClock()},1000);renderPatientTab()}
async function endReview(){const d=await api('/api/reviews/end',{method:'POST',body:JSON.stringify({review_id:state.review.review_id,documentation_completed:true})});clearInterval(state.reviewTimer);state.review=null;state.reviewStarted=null;state.patientData=await api(`/api/patients/${state.patient}?month=${state.month}`);toast(`Review saved: ${d.duration_minutes} min`);renderPatient()}
async function saveNote(){const text=$('#noteText').value.trim();if(!text)return;await api('/api/notes',{method:'POST',body:JSON.stringify({patient_id:state.patient,month:state.month,note_text:text,duration_minutes:Number($('#noteDuration')?.value||3)})});state.patientData=await api(`/api/patients/${state.patient}?month=${state.month}`);toast('Documentation and provider time saved');renderPatient()}
async function saveComm(){const summary=$('#commSummary').value.trim();if(!summary)return;await api('/api/communications',{method:'POST',body:JSON.stringify({patient_id:state.patient,month:state.month,communication_mode:$('#commMode').value,channel:$('#commChannel').value,duration_minutes:Number($('#commDuration').value||0),summary})});state.patientData=await api(`/api/patients/${state.patient}?month=${state.month}`);toast('Communication record saved');renderPatient()}
function closePatient(){clearInterval(state.reviewTimer);state.reviewTimer=null;state.review=null;state.reviewStarted=null;state.patient=null;state.patientData=null;$('#drawer').innerHTML='';if(state.chat){state.chat=false;$('#chat').innerHTML=''}}
function openChat(){if(state.user.role!=='Provider'){toast('Ask Reflect is restricted to provider patient context in this demo.');return}state.chat=true;$('#chat').innerHTML=`<aside class="chat"><div class="chat-head"><div><b>Ask Reflect</b><small>${state.patient?`${state.patient} · ${state.month}`:'Select a patient first'}</small></div><button class="close" id="closeChat">×</button></div><div class="chat-msgs" id="chatMsgs"><div class="msg ai">${state.patient?'I am using only the selected patient’s synthetic data. Ask about modules, time of day, Remote/In Clinic usage, provider time, communication, documentation, modules, timing, or Remote/In Clinic usage.':'Open a patient profile first. V20 intentionally prevents global Ask Reflect answers for provider accounts.'}</div></div>${state.patient?`<div class="chat-prompts">${['Summarize this patient','Which modules were used?','What time of day?','Remote vs clinic','Show provider time','Show billing evidence'].map(x=>`<button data-prompt="${x}">${x}</button>`).join('')}</div><form class="chat-form" id="chatForm"><input id="chatInput" placeholder="Ask about this patient…"><button class="btn btn-primary">Ask</button></form>`:''}<small class="chat-legal">Descriptive analytics only. No diagnosis, treatment recommendation or billing determination.</small></aside>`;$('#closeChat').onclick=()=>{$('#chat').innerHTML='';state.chat=false};$$('[data-prompt]').forEach(b=>b.onclick=()=>sendChat(b.dataset.prompt));if($('#chatForm'))$('#chatForm').onsubmit=e=>{e.preventDefault();sendChat($('#chatInput').value)}}
async function sendChat(text){if(!text.trim())return;const box=$('#chatMsgs');box.insertAdjacentHTML('beforeend',`<div class="msg me">${esc(text)}</div>`);try{const d=await api('/api/chat',{method:'POST',body:JSON.stringify({patient_id:state.patient,month:state.month,message:text})});box.insertAdjacentHTML('beforeend',`<div class="msg ai">${esc(d.answer)}</div>`)}catch(e){box.insertAdjacentHTML('beforeend',`<div class="msg ai">${esc(e.message)}</div>`)}box.scrollTop=box.scrollHeight;$('#chatInput').value=''}
function settings(){let p={};try{p=JSON.parse(localStorage.getItem('reflect-v20-prefs')||'{}')}catch{};$('#modal').innerHTML=`<div class="modal-back"><section class="modal"><div class="page-head"><div><h1>Display & accessibility</h1><p>Light/dark mode, text scaling and color-blind-friendly status styling.</p></div><button class="close" id="closeModal">×</button></div><div class="form-stack"><label class="field"><span>Theme</span><select id="setTheme"><option value="light">Light</option><option value="dark">Dark</option></select></label><label class="field"><span>Font style</span><select id="setFont"><option value="spec">Reflect spec / IBM Plex fallback</option><option value="roboto">Roboto / professional sans</option><option value="times">Times New Roman</option><option value="segoe">Segoe UI</option></select></label><label class="field"><span>Text size</span><select id="setScale"><option value="0.9">Small</option><option value="1">Default</option><option value="1.12">Large</option></select></label><label><input type="checkbox" id="setColor"> Color-blind-friendly status styling</label><div class="callout">The production Reflect app self-hosts IBM Plex fonts. This standalone demo references the family name and falls back to system fonts when it is not installed.</div></div></section></div>`;$('#setTheme').value=p.theme||'light';$('#setFont').value=p.font||'spec';$('#setScale').value=String(p.scale||1);$('#setColor').checked=!!p.colorSafe;$('#closeModal').onclick=()=>$('#modal').innerHTML='';['setTheme','setFont','setScale','setColor'].forEach(id=>$('#'+id).onchange=()=>{localStorage.setItem('reflect-v20-prefs',JSON.stringify({theme:$('#setTheme').value,font:$('#setFont').value,scale:$('#setScale').value,colorSafe:$('#setColor').checked}));prefs()})}
async function logout(){await api('/api/logout',{method:'POST'});clearInterval(state.reviewTimer);Object.assign(state,{user:null,months:[],month:null,page:'patients',patient:null,patientData:null,chat:false,review:null});$('#app').innerHTML=login();bindLogin()}

// ==================== V20 UX OVERRIDES ====================
login = function(){return `<main class="login-v19"><section class="login-v19-card"><div class="login-v19-brand"><span class="brand-glyph">✦</span><div><strong>REFLECT</strong><small>Provider Dashboard · V20</small></div></div><div class="login-v19-copy"><span class="tag coral">Challenge X Demo</span><h1>Provider dashboard</h1><p>Sign in with a dataset-linked demo account. V20 uses detailed V18 synthetic billing-master data.</p></div><form class="login-form-v19" id="loginForm"><label class="field"><span>Email</span><input id="email" type="email" autocomplete="username" required></label><label class="field"><span>Password</span><input id="password" type="password" autocomplete="current-password" required></label><button class="btn btn-primary" type="submit">Sign in</button></form><div id="loginError" class="login-error"></div><div class="login-v19-divider"><span>Demo accounts</span></div><div id="accounts" class="account-grid compact"><div class="skeleton"></div><div class="skeleton"></div></div><p class="login-v19-foot">Synthetic data only · Provider access is panel-scoped · Billing evidence requires human review</p></section></main>`}

shell = function(){return `<div class="shell"><aside class="sidebar"><div class="side-brand"><span class="brand-glyph">✦</span><span><strong>REFLECT</strong><small>Provider Dashboard · V20</small></span></div><div class="user-card"><b>${esc(state.user.display_name)}</b><small>${esc(state.user.role)}${state.user.provider_id?' · '+esc(state.user.provider_id):''}</small></div><nav class="nav">${navItems().map(([id,label])=>`<button data-nav="${id}" class="${state.page===id?'active':''}"><span>${label}</span></button>`).join('')}</nav><div class="side-footer" id="datasetBadge">V18 billing master</div></aside><section class="workspace"><header class="topbar"><span class="crumb" id="crumb">Dashboard</span><div class="top-actions"><button class="btn hide-mobile" id="askBtn">Ask Reflect</button><button class="btn" id="settingsBtn">Display</button><button class="btn" id="logoutBtn">Sign out</button></div></header><main class="page" id="page"></main></section></div><div id="chat"></div><div id="modal"></div><div id="toast" class="toast"></div>`}

boot = async function(){const m=await api('/api/months');state.months=m.months;state.month=m.default;state.billingTab=state.billingTab||'patients';if(state.user.role==='Provider')state.page='patients';else if(state.user.role==='Billing')state.page='billing';else state.page='overview';$('#app').innerHTML=shell();bindShell();const h=await api('/api/health');$('#datasetBadge').textContent=`${h.dataset==='full-v18'?'Full V18':'Sample V18'} · ${fmt(h.patients)} patients / ${fmt(h.providers)} providers`;await renderPage()}

renderPage = async function(){const p=$('#page');if(state.page==='patient'){return renderPatient()}p.innerHTML=`${head('Loading…','Retrieving indexed monthly data')}<div class="skeleton"></div>`;try{if(state.page==='patients')await renderPatients();else if(state.page==='overview'&&state.user.role==='Admin')await renderAdminOverviewV20();else if(state.page==='overview')await renderOverview();else if(state.page==='providerTime')await renderProviderTime();else if(state.page==='explorer')await renderExplorer();else if(state.page==='engagement')await renderEngagement();else if(state.page==='modules')await renderModulesAnalytics();else if(state.page==='platform')await renderPlatformAnalytics();else if(state.page==='review')await renderReview();else if(state.page==='providers')await renderProviders();else if(state.page==='audit')await renderAudit();else if(state.page==='billing'&&(state.user.role==='Billing'||state.user.role==='Admin'))await renderBillingReviewerV20();else await renderBilling()}catch(e){p.innerHTML=`${head('Unable to load this view','The dashboard stopped the request instead of leaving the page in an endless loading state.')}<div class="error-panel"><b>Data request failed</b><p>${esc(e.message)}</p><button class="btn" id="retry">Retry</button></div>`;bindMonth();$('#retry').onclick=renderPage}}

openPatient = async function(id,keepTab=false){try{state.previousPage=state.page==='patient'?(state.previousPage||'patients'):state.page;state.patient=id;state.patientData=null;if(!keepTab)state.patientTab='Summary';state.page='patient';$('#page').innerHTML=`<div class="patient-page-loading"><button class="btn" id="patientBack">← Back</button><div class="skeleton"></div><h2>Loading ${esc(id)}</h2><p>Preparing V18 patient sessions and provider billing timeline…</p></div>`;if($('#patientBack'))$('#patientBack').onclick=closePatient;state.patientData=await api(`/api/patients/${id}?month=${state.month}`);renderPatient()}catch(e){$('#page').innerHTML=`<div class="patient-page-error"><button class="btn" id="patientBack">← Back</button><div class="error-panel"><h2>Patient detail unavailable</h2><p>${esc(e.message)}</p><button class="btn btn-primary" id="retryPatient">Retry</button></div></div>`;$('#patientBack').onclick=closePatient;$('#retryPatient').onclick=()=>openPatient(id,true)}}

renderPatient = function(){if(!state.patientData){return}const d=state.patientData,p=d.patient;const tabs=['Summary','Reflect Mobile','Reflect XR','Monthly Activity','Provider Activity','Communication','Billing','Insights'];$('#page').innerHTML=`<section class="patient-page-v19"><div class="patient-page-top"><button class="btn" id="patientBack">← Back to ${state.previousPage==='review'?'Review Queue':'Patients'}</button><div class="patient-page-title"><span class="eyebrow-inline">PATIENT WORKSPACE · ${state.month}</span><h1>${p.patient_id}</h1><p>${esc(d.provider.provider_display_name)} · ${esc(d.provider.provider_id||'')}</p><div class="patient-head-tags">${tag(p.platform_preference,'coral')}${tag(p.trend_pattern)}${tag(p.preferred_time_band)}${tag(d.goal.title)}</div></div><div class="patient-page-actions"><select id="patientMonth">${state.months.map(m=>`<option ${m===state.month?'selected':''}>${m}</option>`).join('')}</select><span class="tag ${d.billing_master==='V18.2'?'good':''}">${d.billing_master==='V18.2'?'V18.2 detailed data':'Runtime detail'}</span></div></div><div class="tabs patient-tabs-v19">${tabs.map(x=>`<button data-tab="${x}" class="${state.patientTab===x?'active':''}">${x}</button>`).join('')}</div><div class="patient-page-body" id="patientBody"></div></section>`;$('#patientBack').onclick=closePatient;$('#patientMonth').onchange=async e=>{state.month=e.target.value;await openPatient(state.patient,true)};$$('[data-tab]').forEach(b=>b.onclick=()=>{state.patientTab=b.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderPatientTab()});renderPatientTab()}

closePatient = function(){clearInterval(state.reviewTimer);state.reviewTimer=null;state.review=null;state.reviewStarted=null;state.patient=null;state.patientData=null;state.page=state.previousPage||'patients';state.previousPage=null;if(state.chat){state.chat=false;$('#chat').innerHTML=''};$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===state.page));renderPage()}

async function renderAdminOverviewV20(){const p=$('#page');const [d,a,bt]=await Promise.all([api(`/api/overview?month=${state.month}`),api(`/api/analytics?month=${state.month}`),api(`/api/billing/queue?month=${state.month}&view=providers&page=1`)]);const m=d.month||{},k=a.kpis||{};p.innerHTML=head('Organization Overview','Executive analytics across patient engagement, provider operations, and V18 billing-support evidence.')+`<div class="analytics-hero admin-hero"><div><span class="eyebrow-inline">ORGANIZATION · ${state.month}</span><h2>Engagement, provider workload, and billing readiness</h2><p>Use the cards below to move from organization-wide patterns into individual providers and patient evidence.</p></div><div class="hero-stat"><b>${fmt(m.active_rate||0)}%</b><span>patient active rate</span></div></div><div class="kpis admin-kpis">${kpi('Patients',fmt(m.patients||k.cohort_patients||0),'synthetic population')}${kpi('Active patients',fmt(m.active_patients||k.active_patients||0),'selected month')}${kpi('Sessions',fmt(m.sessions||k.sessions||0),'Mobile + XR')}${kpi('Avg engagement',fmt(m.engagement||k.engagement||0),'descriptive index')}${kpi('Avg completion',pct(m.completion||k.completion||0),'session completion')}${kpi('Providers',fmt(m.providers||bt.total||0),'organization panels')}${kpi('Provider time',`${fmt(m.provider_time_hours||0)} hr`,'exact V18.2 monthly total')}${kpi('Review queue',fmt(m.review_suggested||0),'workflow marker')}</div><div class="admin-nav-cards"><button data-go="patients"><b>Patient Directory</b><span>Search and open full patient workspaces</span></button><button data-go="providers"><b>Provider Panels</b><span>Panel scale and provider metadata</span></button><button data-go="providerTime"><b>Provider Activity</b><span>Review, communication, documentation</span></button><button data-go="billing"><b>Billing Oversight</b><span>Patient/provider evidence and RTM reports</span></button><button data-go="explorer"><b>Explorer</b><span>Interactive cohort analysis</span></button><button data-go="engagement"><b>Engagement</b><span>Patterns, recency, completion matrix</span></button><button data-go="modules"><b>Modules</b><span>Separate Mobile and XR usage</span></button><button data-go="platform"><b>Platform</b><span>Mobile/XR mix and trends</span></button></div><div class="analytics-grid"><div class="card chart-card"><div class="card-head"><div><h3>Monthly session trend</h3><p>Organization activity across available months.</p></div></div><div class="card-body">${svgLineChart(a.trend||[],[{key:'sessions',label:'Sessions'}],{})}</div></div><div class="card"><div class="card-head"><div><h3>Platform mix</h3><p>Estimated organization distribution.</p></div></div><div class="card-body">${donutSummary(a.platform_mix||a.monthly_platform||[],'patients')}</div></div></div><div class="analytics-grid"><div class="card"><div class="card-head"><div><h3>Engagement patterns</h3><p>Longitudinal synthetic behavior.</p></div></div><div class="card-body">${rankBars(a.patterns||[])}</div></div><div class="card"><div class="card-head"><div><h3>Recent activity</h3><p>Current-month activity bands.</p></div></div><div class="card-body">${rankBars(a.activity||[])}</div></div><div class="card"><div class="card-head"><div><h3>Provider billing workload</h3><p>Top providers by detailed V18 provider time.</p></div></div><div class="card-body">${rankBars((bt.rows||[]).slice(0,10).map(x=>({label:x.provider_id||String(x.provider_key),value:x.total_provider_minutes||0})))}</div></div></div>`;bindMonth();$$('[data-go]').forEach(b=>b.onclick=()=>{state.page=b.dataset.go;$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===state.page));renderPage()})}

async function renderBillingReviewerV20(){const p=$('#page');state.billingTab=state.billingTab||'patients';const view=state.billingTab;const q=await api(`/api/billing/queue?month=${state.month}&view=${view}&page=1`);let body='';if(view==='patients'){body=`<div class="card"><div class="card-head"><div><h3>Patient billing-support records</h3><p>One provider + one patient + one month. Sorted by total provider time.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Patient</th><th>Provider</th><th>Provider time</th><th>Review</th><th>Communication</th><th>Documentation</th><th>Activity days</th><th>Synthetic amount*</th><th>Status</th><th>Report</th></tr></thead><tbody>${q.rows.map(r=>`<tr><td><b>${r.patient_id}</b></td><td>${r.provider_id}<br><small>${esc(r.provider_display_name||'')}</small></td><td><b>${fmt(r.total_provider_minutes)} min</b></td><td>${fmt(r.data_review_minutes)} min<br><small>${fmt(r.data_review_count)} events</small></td><td>${fmt(r.communication_minutes)} min<br><small>${fmt(r.communication_count)} events</small></td><td>${fmt(r.documentation_minutes)} min<br><small>${fmt(r.documentation_count)} events</small></td><td>${fmt(r.provider_activity_days)}</td><td><b>$${Number(r.synthetic_demo_amount||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</b></td><td>${tag(r.billing_status||'REQUIRES_REVIEW','coral')}</td><td><a class="btn" target="_blank" href="/api/billing/report?patient_id=${r.patient_id}&month=${state.month}">PDF</a></td></tr>`).join('')}</tbody></table></div></div>`}else{body=`<div class="card"><div class="card-head"><div><h3>Provider billing workload</h3><p>Provider-level aggregation from detailed patient-specific events. Click a provider to inspect the patient breakdown.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Provider</th><th>Assigned patients</th><th>Patients with activity</th><th>Review min</th><th>Communication min</th><th>Documentation min</th><th>Total min</th><th>Synthetic amount*</th><th>Open</th></tr></thead><tbody>${q.rows.map(r=>`<tr><td><b>${r.provider_id}</b><br><small>${esc(r.provider_display_name||'')}</small></td><td>${fmt(r.assigned_patient_count)}</td><td>${fmt(r.patients_with_provider_activity)}</td><td>${fmt(r.data_review_minutes)}</td><td>${fmt(r.communication_minutes)}</td><td>${fmt(r.documentation_minutes)}</td><td><b>${fmt(r.total_provider_minutes)}</b></td><td><b>$${Number(r.synthetic_demo_amount||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</b></td><td><button class="btn" data-bill-provider="${r.provider_id}">Details</button></td></tr>`).join('')}</tbody></table></div></div>`}const t=q.totals||{};p.innerHTML=head('Billing & RTM Review','V18.2 detailed provider activity organized for billing-support review. No automatic reimbursement determination.')+`<div class="kpis">${kpi(view==='patients'?'Patient records':'Providers',fmt(t.records||q.total||0),state.month)}${kpi('Provider time',`${fmt(t.total_provider_minutes||0)} min`,'review + communication + documentation')}${kpi('Data review',`${fmt(t.data_review_minutes||0)} min`)}${kpi('Communication',`${fmt(t.communication_minutes||0)} min`)}${kpi('Documentation',`${fmt(t.documentation_minutes||0)} min`)}${kpi('Synthetic amount*',`$${Number(t.synthetic_demo_amount||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`,`demo rate $${fmt(q.demo_hourly_rate||0)}/hr`)}</div><div class="billing-review-tabs"><button data-btab="patients" class="${view==='patients'?'active':''}">Patients</button><button data-btab="providers" class="${view==='providers'?'active':''}">Providers</button></div><div class="callout"><b>Billing evidence rule</b><p>Provider time is calculated from timestamped DATA_REVIEW + COMMUNICATION + DOCUMENTATION events for one patient. Patient engagement time is separate monitoring context. <b>*Synthetic amount</b> uses a configurable demo hourly rate and is not a payer reimbursement determination.</p></div>${body}`;bindMonth();$$('[data-btab]').forEach(b=>b.onclick=()=>{state.billingTab=b.dataset.btab;renderBillingReviewerV20()});$$('[data-bill-provider]').forEach(b=>b.onclick=()=>openBillingProviderV20(b.dataset.billProvider))}

async function openBillingProviderV20(providerId){const d=await api(`/api/billing/provider/${providerId}?month=${state.month}`);const p=$('#page'),s=d.summary||{};p.innerHTML=`<div class="page-head"><div><button class="btn" id="billingBack">← Billing Review</button><h1>${esc(d.provider.provider_display_name)}</h1><p>${d.provider.provider_id} · ${d.provider.region_code||'—'} · ${state.month}</p></div></div><div class="kpis">${kpi('Assigned patients',fmt(s.assigned_patient_count))}${kpi('Patients with activity',fmt(s.patients_with_provider_activity))}${kpi('Data review',`${fmt(s.data_review_minutes)} min`)}${kpi('Communication',`${fmt(s.communication_minutes)} min`)}${kpi('Documentation',`${fmt(s.documentation_minutes)} min`)}${kpi('Total provider time',`${fmt(s.total_provider_minutes)} min`)}${kpi('Synthetic amount*',`$${Number(s.synthetic_demo_amount||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`,'demo rate only')}</div><div class="analytics-grid"><div class="card"><div class="card-head"><div><h3>Provider work profile</h3><p>Synthetic workflow characteristics.</p></div></div><div class="card-body insight-stack">${Object.entries(d.profile||{}).filter(([k])=>!['provider_key','created_utc','updated_utc'].includes(k)).slice(0,10).map(([k,v])=>`<div class="insight-item"><span>${esc(k.replaceAll('_',' '))}</span><b>${esc(v)}</b></div>`).join('')}</div></div><div class="card"><div class="card-head"><div><h3>Access sessions</h3><p>Operational login context; not automatically billable.</p></div></div><div class="card-body">${rankBars((d.access_sessions||[]).slice(0,12).map(x=>({label:(x.login_eastern||x.login_utc||'').slice(0,16),value:Number(x.duration_seconds||0)/60})))}</div></div></div><div class="card"><div class="card-head"><div><h3>Patient-specific provider time</h3><p>Each row can be reviewed independently for supporting documentation.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Patient</th><th>Review</th><th>Communication</th><th>Documentation</th><th>Total</th><th>Synthetic amount*</th><th>Activity days</th></tr></thead><tbody>${(d.patients||[]).map(r=>`<tr><td><b>${r.patient_id}</b></td><td>${fmt(r.data_review_minutes)} min</td><td>${fmt(r.communication_minutes)} min</td><td>${fmt(r.documentation_minutes)} min</td><td><b>${fmt(r.total_provider_minutes)} min</b></td><td>$${Number(r.synthetic_demo_amount||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</td><td>${fmt(r.provider_activity_days)}</td></tr>`).join('')}</tbody></table></div></div>`;$('#billingBack').onclick=renderBillingReviewerV20}

(async()=>{prefs();try{const s=await api('/api/session');if(s.authenticated){state.user=s.user;await boot()}else{$('#app').innerHTML=login();bindLogin()}}catch(e){$('#app').innerHTML=`<div class="fatal"><div class="error-panel"><h2>Dashboard unavailable</h2><p>${esc(e.message)}</p></div></div>`}})();
